// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint128 amount, uint128 withdrawAmount, address caller, address other) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(amount > 0 && withdrawAmount > 0 && withdrawAmount <= amount);

        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success,) = address(c).call{value: amount}("");
        require(success, "deposit fail");

        vm.deal(other, amount);
        vm.prank(other);
        (success,) = address(c).call{value: amount}("");
        require(success, "deposit fail");

        vm.prank(caller);
        try c.withdraw() { } catch { }

        uint256 totalBalances = c.balances(caller) + c.balances(other);
        assertTrue(totalBalances <= address(c).balance);
    }
}
